// Parse the processing request
const requestData = msg.payload;
const processingType = requestData.type || 'both';
const startDate = requestData.startDate;
const endDate = requestData.endDate;

// Validate dates
if (!startDate || !endDate) {
    msg.statusCode = 400;
    msg.payload = {
        status: 'error',
        message: 'startDate and endDate are required'
    };
    return msg;
}

// Prepare command
msg.command = `cd /home/jc/Documents/Horse-race-ai-v2.04 && python tools/node_red_data_processor.py --start-date ${startDate} --end-date ${endDate} --type ${processingType}`;

msg.payload = {
    processing: true,
    startDate: startDate,
    endDate: endDate,
    dataType: processingType,
    command: msg.command,
    source: 'web_dashboard'
};

// Send success response immediately
msg.res.json({
    status: 'success',
    message: 'Processing started',
    request: {
        type: processingType,
        startDate: startDate,
        endDate: endDate
    }
});

node.status({fill: "yellow", shape: "dot", text: `Processing ${processingType} ${startDate}-${endDate}`});

return msg;

// Start the full data processing pipeline
msg.res.json({
    status: 'success',
    message: 'Full pipeline started',
    timestamp: new Date().toISOString()
});

// Trigger the pipeline
msg.payload = {
    trigger: 'full_pipeline',
    timestamp: new Date().toISOString(),
    source: 'web_dashboard'
};

node.status({fill: "blue", shape: "dot", text: "Starting full pipeline"});

return msg;

// Pipeline step completed successfully
const timestamp = new Date().toISOString();

msg.payload = {
    status: 'success',
    timestamp: timestamp,
    message: 'Pipeline step completed',
    step: 'data_download'
};

node.status({fill: "green", shape: "dot", text: "Step completed"});

return msg;

// Trigger API startup
msg.res.json({
    status: 'success',
    message: 'API startup triggered',
    timestamp: new Date().toISOString()
});

msg.payload = {
    trigger: 'start_apis',
    timestamp: new Date().toISOString(),
    source: 'web_dashboard'
};

node.status({fill: "blue", shape: "dot", text: "Starting APIs"});

return msg;

// Check system status
const status = {
    database: true,  // Mock for now
    apis: false,     // Mock for now
    pipeline: 'ready',
    timestamp: new Date().toISOString()
};

// Try to check actual status (simplified)
// In production, you'd check actual services

msg.payload = status;

msg.res.json(status);

node.status({fill: "green", shape: "dot", text: "Status checked"});

return msg;

// Get processing statistics
// In production, this would query the database
const stats = {
    cardsToday: Math.floor(Math.random() * 50) + 10,
    resultsToday: Math.floor(Math.random() * 30) + 5,
    totalCards: Math.floor(Math.random() * 5000) + 1000,
    totalResults: Math.floor(Math.random() * 3000) + 500,
    timestamp: new Date().toISOString()
};

msg.payload = stats;
msg.res.json(stats);

node.status({fill: "green", shape: "dot", text: "Stats retrieved"});

return msg;

// Prepare NTFY notification request
const title = msg.payload.title || 'System Notification';
const message = msg.payload.message || 'No message provided';
const topic = msg.payload.topic || 'horserace-system';
const tags = msg.payload.tags || 'system';
const priority = msg.payload.priority || 'default';

// Set the URL for NTFY
msg.url = `http://localhost:8082/${topic}`;

// Set headers
msg.headers = {
    'Content-Type': 'text/plain',
    'Title': title,
    'Tags': tags,
    'Priority': priority
};

// Set the message as payload
msg.payload = message;

return msg;

// Handle NTFY response
if (msg.statusCode === 200) {
    msg.payload = {
        status: 'success',
        message: 'Notification sent successfully',
        ntfyResponse: msg.payload
    };
} else {
    msg.payload = {
        status: 'error',
        message: 'Failed to send notification',
        statusCode: msg.statusCode,
        error: msg.payload
    };
}

return msg;

// Send startup notification
msg.payload = {
    title: '🎯 C2 System Online',
    message: `Horse Racing AI Command & Control Center is now operational! Enhanced dashboard with NTFY integration available.`,
    topic: 'horserace-system',
    tags: 'startup,c2,system,online',
    priority: 'default'
};

return msg;
